let clipTimer;
const CLIP=[
 ['One result. Several possible claims.','A tumor grows more slowly after treatment. That is encouraging. But which claim does it support?','Tumor growth slows','Observation',8],
 ['Inside the tumor','In this invented example, the human tumor is grown in a mouse. The drug suppresses the human target, and tumor growth slows.','Human tumor','Pathway suppressed',9],
 ['Outside the tumor','The normal intestine belongs to the mouse. Its corresponding pathway stays active at the achieved exposure. No injury is detected.','Mouse intestine','Pathway remains active',10],
 ['Where the inference stops','We have not tested what happens when normal human intestine experiences the relevant pathway inhibition. Human risk remains unresolved.','Human intestine','Unanswered question',12],
 ['Connect the evidence','An IND connects biological effects, drug exposure, potential harm, product quality, and a specific clinical plan.','The whole argument','Several kinds of evidence',10],
 ['Choose the next useful experiment','Keep the useful result. Locate the missing condition. Choose evidence that addresses it.','Observation → inference → next evidence','Your scientific judgment',6]
];
function termSource(i){const s=SOURCES[i];return `<a class="source-inline" href="${s.url}" target="_blank" rel="noopener noreferrer">Read the source: ${s.label} ↗</a>`;}
function lessonEnd(next){return `<div class="action-row"><button class="text-button" data-action="sources">Sources & assumptions ↗</button>${next?`<button class="button primary" data-lesson="${next}">Next: ${LABS.find(l=>l.id===next)?.title||BRIEFS.find(l=>l.id===next)?.title} →</button>`:''}</div>`;}
function tissue(name,sub,active){return `<div class="tissue"><p class="eyebrow">${name}</p><div class="cell-field ${active?'engaged':''}" aria-hidden="true"><span class="molecule-dot">●</span><span class="bio-cell">Y</span><span class="bio-cell">Y</span><span class="bio-cell">Y</span></div><strong>${active?'Pathway suppressed':'Pathway remains active'}</strong><p>${sub}</p></div>`;}
function modelLesson(){return heading('02','What did the model actually test?','Change one biological condition. Watch which inference changes—and which questions remain.')+`<div class="lab-grid"><div><section class="lab-surface"><div class="surface-bar"><strong>The same animal. Two biological contexts.</strong><span class="tag">Invented example</span></div><div class="model-canvas"><p class="model-intro">A human tumor is grown in a mouse. Assume XYZ1 is also needed for normal human intestinal function.</p><div class="tissue-pair">${tissue('HUMAN TUMOR','Observed: tumor growth slows.',true)}${tissue('NORMAL MOUSE INTESTINE',state.modelEngaged?'No injury detected in this hypothetical study.':'Observed: no injury detected.',state.modelEngaged)}</div><div class="control-block"><label class="toggle"><input type="checkbox" id="model-engaged" ${state.modelEngaged?'checked':''}><span class="toggle-track" aria-hidden="true"></span><span>Suppress XYZ1 in the mouse intestine</span></label><p>Counterfactual control: hold the stated injury observation constant and change target engagement.</p></div></div><div class="selected-evidence" aria-live="polite"><p class="eyebrow">${state.modelEngaged?'A MORE RELEVANT CONDITION':'THE MISSING CONDITION'}</p><h3>${state.modelEngaged?'The negative finding becomes more informative.':'An unperturbed pathway cannot test this on-target risk.'}</h3><p>${state.modelEngaged?'Now the mouse intestine experiences pathway suppression without detected injury under these study conditions. Human risk remains uncertain: exposure, duration, assay sensitivity, and biological differences still matter.':'Tumor activity is supported in this model. Because the normal mouse intestinal pathway was not suppressed, its lack of injury does not establish that normal human intestine will be spared.'}</p></div></section><div class="action-row"><button class="button" data-action="experiment">Design the next experiment</button><button class="button primary" data-action="challenge">Repair a claim →</button></div>${lessonEnd('exposure')}</div>${notebook('Absence of injury has meaning only in relation to what the model was capable of testing.','Adding more observations from the same biological setting can improve precision. It cannot introduce a missing target perturbation.')}</div>`;}
function exposureMetrics(){const f=state.bioavailability,h=state.halfLife,k=Math.log(2)/h;return {initial:100*f,auc:100*f/k,residual:100*f*Math.exp(-k*24)};}
function exposureChart(){const m=exposureMetrics();const compact=window.matchMedia('(max-width:700px)').matches;const width=compact?320:580,scale=compact?10:20;const path=(f,h)=>Array.from({length:97},(_,i)=>{const t=i/4;return `${i?'L':'M'}${58+t*scale},${245-100*f*Math.exp(-Math.log(2)/h*t)*1.95}`;}).join(' ');return `<svg viewBox="0 0 ${width} 300" role="img" aria-label="Model concentration over 24 hours. Selected initial concentration ${m.initial.toFixed(0)} units, remaining concentration at 24 hours ${m.residual.toFixed(1)} units. Dashed baseline uses 50 percent bioavailability and a 4 hour half-life."><text x="58" y="22" class="chart-label">${compact?"Concentration (a.u.)":"Plasma concentration (arbitrary units)"}</text>${[0,25,50,75,100].map(v=>`<line x1="58" y1="${245-v*1.95}" x2="${58+24*scale}" y2="${245-v*1.95}" class="grid-line"/><text x="47" y="${250-v*1.95}" text-anchor="end">${v}</text>`).join('')}<path d="${path(.5,4)}" fill="none" stroke="#8793ab" stroke-width="2.5" stroke-dasharray="7 6"/><path d="${path(state.bioavailability,state.halfLife)}" fill="none" stroke="#2f54ed" stroke-width="3.5"/>${(compact?[0,12,24]:[0,6,12,18,24]).map(v=>`<text x="${58+v*scale}" y="268" text-anchor="middle">${v}</text>`).join('')}<text x="${58+12*scale}" y="293" text-anchor="middle">${compact?"Time (hours)":"Hours after systemic entry"}</text></svg>`;}
function exposureLesson(){return heading('03','Dose is an input. Exposure is what happens.','Hold the administered dose constant. Change bioavailability or half-life to explore the concentration–time curve.')+`<div class="lab-grid"><div><section class="lab-surface"><div class="surface-bar"><strong>A small model with visible assumptions</strong><span class="tag">Teaching simulation</span></div><div class="exposure-body"><div class="chart-legend"><span><i></i> Your settings</span><span><i class="baseline"></i> Baseline</span></div><div id="exposure-chart">${exposureChart()}</div><div class="range-row"><label for="bioavailability">Systemic bioavailability, F <output id="f-value">${Math.round(state.bioavailability*100)}%</output></label><input id="bioavailability" type="range" min="10" max="100" step="5" value="${state.bioavailability*100}" aria-describedby="f-help"><p id="f-help">Fraction of the administered dose reaching systemic circulation. For an oral drug, this reflects absorption and presystemic loss.</p></div><div class="range-row"><label for="half-life">Elimination half-life <output id="h-value">${state.halfLife} h</output></label><input id="half-life" type="range" min="1" max="12" step="1" value="${state.halfLife}" aria-describedby="h-help"><p id="h-help">Time for concentration to halve in this model. It is not necessarily the duration of a biological effect.</p></div><div class="metrics" id="exposure-metrics" aria-live="polite"></div><details class="assumptions"><summary>Open the model: equation and assumptions</summary><p><code>C(t) = 100 × F × exp(−ln(2) × t / t½)</code></p><p>The dose-to-volume scale is fixed at 100 arbitrary concentration units. Drug enters the modeled systemic compartment instantaneously. Elimination is first order; this omits the oral absorption phase, tissue distribution, metabolites, repeat dosing, and variability.</p><p>AUC from 0 to infinity = 100 × F × t½ / ln(2). Changing half-life here holds volume fixed. There is no efficacy or injury threshold in this model: concentration alone cannot tell us either outcome.</p></details></div></section><div class="action-row"><button class="button" data-action="reset-exposure">Reset baseline</button><button class="button primary" data-action="challenge">Try a formulation change →</button></div>${lessonEnd('cmc')}</div>${notebook('A large oral dose with little systemic exposure is not, by itself, reassuring safety evidence. Also consider local gut exposure and what was actually measured.','Make assumptions inspectable. A simple PK model helps isolate a relationship, but it does not predict clinical efficacy or select a human dose.')}</div>`;}
function updateExposure(){const m=exposureMetrics();$('#exposure-chart').innerHTML=exposureChart();$('#f-value').textContent=Math.round(state.bioavailability*100)+'%';$('#h-value').textContent=state.halfLife+' h';$('#exposure-metrics').innerHTML=`<div><small>Initial concentration</small><strong>${m.initial.toFixed(0)} <span>units</span></strong></div><div><small>AUC₀–∞ / total exposure</small><strong>${m.auc.toFixed(0)} <span>unit·h</span></strong></div><div><small>Remaining at 24 h</small><strong>${m.residual.toFixed(1)} <span>units</span></strong></div>`;}
function briefLesson(){const b=BRIEF_CONTENT[state.lesson];const next={cmc:'clinical',clinical:'people',people:'review'}[state.lesson];return heading('BRIEFING',b.title,b.lede)+`<div class="lab-grid"><div><section class="lab-surface"><div class="surface-bar"><strong>${BRIEFS.find(b=>b.id===state.lesson).title}</strong><span class="tag">3-minute briefing</span></div><div class="brief-steps">${b.cards.map((c,i)=>`<article><span class="step-number">0${i+1}</span><div><h2>${c[0]}</h2><p>${c[1]}</p></div></article>`).join('')}</div><div class="selected-evidence"><h3>${b.question}</h3><p>${b.answer}</p></div></section><p class="callout">${b.terms}</p>${termSource(b.source)}${state.lesson==='review'?`<p>${termSource(8)} · ${termSource(10)}</p>`:''}${lessonEnd(next)}</div>${notebook('The goal is to understand the decisions and contribute useful evidence when collaborating with development specialists.',b.lens)}</div>`;}
function render(){nav();$('#lesson').innerHTML=state.lesson==='map'?mapLesson():state.lesson==='model'?modelLesson():state.lesson==='exposure'?exposureLesson():briefLesson();if(state.lesson==='map')updateStream();if(state.lesson==='exposure')updateExposure();document.title=(LABS.find(x=>x.id===state.lesson)||BRIEFS.find(x=>x.id===state.lesson)).title+' · IND Evidence Lab';}
function navigate(id,{focus=true}={}){if(![...LABS,...BRIEFS].some(l=>l.id===id))throw new Error('Unknown lesson');stopClip();if($('#modal').open)$('#modal').close();state.lesson=id;history.replaceState(null,'','#'+id);render();if(focus){$('#lesson').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}return readState();}
function modal(kicker,html){stopClip();$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=html;const title=$('#modal-body h2');if(title)title.id='dialog-title';if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function sources(){modal('PRIMARY SOURCES','<h2>Follow the evidence back to its source.</h2><p>US FDA pathway, with a small-molecule foundation. These are selected sources for the prototype, not a universal IND checklist.</p><ul class="source-list">'+SOURCES.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.label} ↗</a></li>`).join('')+'</ul><div class="callout">Regulations set requirements. Guidance explains agency thinking in its stated context. The workstream map is a teaching framework. XYZ1 and all model data are invented. ICH S9 is specific to anticancer drugs for patients with advanced cancer and limited treatment options.</div><p>Source check: 14 September 2026. This is an educational prototype, not a submission-ready package.</p>');}
function about(){modal('THE SCIENTIFIC PERSPECTIVE','<h2>For the scientist at the handoff.</h2><p>For early R&D scientists who already understand biology and drug discovery, but do not yet understand how a development candidate becomes a clinical-stage drug.</p><p>The perspective is that of a high-agency mechanistic, experimental, and computational biologist who uses AI: ask better questions, inspect assumptions, design discriminating experiments, and make the evidence legible.</p><div class="callout">What mechanism could explain this? What can this model tell us? Which experiment would change the decision?</div><p>Start with a short explanation, manipulate a relationship, then compare your reasoning with a worked answer. Build useful development literacy and better collaboration with specialists.</p><p>Version 0.1 contains three interactive labs and four briefings. We will build the deeper course one useful lesson at a time.</p>');}
function course(){modal('THE COURSE WE CAN BUILD TOGETHER',`<h2>From discovery knowledge to development judgment.</h2><p>Three interactive labs and four briefing cards are available now. The 16-chapter outline below is the longer-term plan; linked previews cover selected concepts, not whole chapters.</p><div class="course-list">${COURSE.map((c,i)=>`<div class="course-row"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${c[0]}</strong><p>${c[1]}</p>${c[2]?`<button class="text-button" data-lesson="${c[2]}">Open ${['cmc','clinical','people','review'].includes(c[2])?'briefing':'related lab'} →</button>`:'<small>Planned lesson</small>'}</div></div>`).join('')}</div><p>Chapters 13–16 extend the foundation into specific contexts. They are not requirements for every IND.</p>`);}
function challenge(){const q=QUESTIONS[state.lesson];if(!q)return;modal('TRY → EXPLAIN → TRANSFER',`<h2>${q.title}</h2><p>${q.prompt}</p><div class="choices">${q.options.map((o,i)=>`<button class="choice" data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${o[0]}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div><button class="text-button hint-button" data-action="hint">Show a hint</button>`);}
function answer(index){const q=QUESTIONS[state.lesson];if(!q||!q.options[index])return;const o=q.options[index];state.answers[state.lesson]=index;document.querySelectorAll('[data-answer]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.answer)===index);b.setAttribute('aria-pressed',String(Number(b.dataset.answer)===index));});$('#feedback').innerHTML=`<div class="feedback ${o[2]?'good':''}"><strong>${o[2]?'A well-bounded conclusion.':'Look at the inference.'}</strong><p>${o[1]}</p>${o[2]?`<button class="button primary" data-lesson="${state.lesson==='map'?'model':state.lesson==='model'?'exposure':'cmc'}">Continue learning →</button>`:''}</div>`;}
function experiment(){modal('EXPERIMENTAL JUDGMENT',`<h2>Address the missing condition.</h2><p>For the original model, propose a study that could inform on-target intestinal risk. There is more than one defensible design.</p><label class="field-label" for="experiment-note">I would use a model where… measure… and change my decision if…</label><textarea id="experiment-note" rows="5" placeholder="Think about target engagement, exposure, tissue function, and time.">${escapeHtml(state.experimentNote||'')}</textarea><p class="fine-print">Your note stays in this page session. The worked answer is prewritten; your text is not sent to AI.</p><button class="button primary" data-action="worked">Compare with a worked answer</button><div id="worked-answer"></div>`);}
function worked(){$('#worked-answer').innerHTML='<div class="callout"><strong>One defensible sketch</strong><p>Use a justified model of normal human intestinal function in which the drug engages XYZ1. Measure pathway suppression, exposure, and a functional or injury readout over time. Interpret a negative finding with assay sensitivity, duration, and model limitations.</p><p>Human intestinal organoids could contribute mechanistic evidence, but one assay is not a complete safety package. A relevant animal model also needs a rationale based on pharmacology, exposure, and metabolism.</p></div><p><strong>Self-check:</strong> Did your design introduce the missing target perturbation? Did it measure function as well as engagement? What result would change your next step?</p>';}
function promptText(){return `Act as a rigorous teaching partner for an early R&D scientist who understands biology and discovery, learning US IND development.\n\nCurrent lesson: ${(LABS.find(x=>x.id===state.lesson)||BRIEFS.find(x=>x.id===state.lesson)).title}.\n${state.lesson==='model'?`Invented example: a human xenograft responds; mouse intestinal XYZ1 suppression is ${state.modelEngaged?'present':'absent'}; no intestinal injury is detected. Human intestine is assumed to need XYZ1 function. Separate model observations from human inferences.`:state.lesson==='exposure'?`Toy model: C(t)=100*F*exp(-ln(2)*t/halfLife), F=${state.bioavailability}, half-life=${state.halfLife} h. Systemic entry is instantaneous, units are arbitrary, no clinical thresholds. Do not use it to choose a human dose.`:'Help me connect the evidence to a specific proposed human study.'}\n\nTeach one concept at a time. Separate observation, inference, and missing evidence. Ask one focused question, then wait. Use primary FDA or ICH sources for regulatory claims, verify their current status, and state when a claim is scientific interpretation or when evidence is missing. Do not invent mandatory studies, clinical outcomes, or FDA decisions.\n\nStarting references:\n${SOURCES.slice(0,6).map(s=>s.label+': '+s.url).join('\n')}`;}
function ai(){modal('TAKE THE QUESTION TO YOUR AI TOOL',`<h2>Use AI to sharpen your reasoning.</h2><p>This prompt includes the current lesson and model settings. Copy it into your preferred AI tool, then check its claims against the sources.</p><label class="field-label" for="ai-prompt">Editable learning prompt</label><textarea id="ai-prompt" rows="11">${escapeHtml(promptText())}</textarea><div class="action-row"><span class="fine-print" id="copy-status" aria-live="polite">This prototype does not connect to a live model.</span><button class="button primary" data-action="copy-prompt">Copy prompt</button></div>`);}
async function copyPrompt(){try{await navigator.clipboard.writeText($('#ai-prompt').value);$('#copy-status').textContent='Copied. Paste into your AI tool when ready.';}catch{$('#ai-prompt').focus();$('#ai-prompt').select();$('#copy-status').textContent='Select and copy the prompt using your keyboard.';}}
function stopClip(){clearTimeout(clipTimer);state.clipPlaying=false;}
function clip(){state.clipStep=0;modal('55-SECOND VISUAL LESSON · CAPTIONED, NO AUDIO','<h2>Watch the evidence split.</h2><div id="clip-stage"></div><div class="clip-controls"><button class="button" data-action="clip-prev">← Back</button><button class="button primary" data-action="clip-play" id="clip-play">Play</button><button class="button" data-action="clip-next">Next →</button></div><details class="transcript"><summary>Read the complete transcript</summary>'+CLIP.map(s=>`<p><strong>${s[0]}</strong> ${s[1]}</p>`).join('')+'</details>');drawClip();}
function drawClip(){const c=CLIP[state.clipStep];$('#clip-stage').innerHTML=`<div class="clip-art"><p class="eyebrow">${String(state.clipStep+1).padStart(2,'0')} / 06</p><div class="clip-symbol ${state.clipStep===3?'unknown':''}" aria-hidden="true">${['↗','Y','Y','?','⇄','→'][state.clipStep]}</div><h3>${c[2]}</h3><span>${c[3]}</span></div><h3>${c[0]}</h3><p class="clip-caption">${c[1]}</p><div class="clip-dots">${CLIP.map((_,i)=>`<button aria-label="Scene ${i+1}" data-scene="${i}" aria-pressed="${i===state.clipStep}" class="${i===state.clipStep?'active':''}"></button>`).join('')}</div>`;$('#clip-play').textContent=state.clipPlaying?'Pause':state.clipStep===5?'Replay':'Play';$('[data-action="clip-prev"]').disabled=state.clipStep===0;$('[data-action="clip-next"]').disabled=state.clipStep===5;}
function scheduleClip(){clearTimeout(clipTimer);clipTimer=setTimeout(()=>{if(!state.clipPlaying)return;if(state.clipStep===5){stopClip();drawClip();return;}state.clipStep++;drawClip();scheduleClip();},CLIP[state.clipStep][4]*1000);}
function playClip(){if(state.clipPlaying){stopClip();drawClip();return;}if(state.clipStep===5)state.clipStep=0;state.clipPlaying=true;drawClip();scheduleClip();}
function setModel(value){if(typeof value!=='boolean')throw new Error('engaged must be a boolean');state.modelEngaged=value;if(state.lesson==='model')render();return readState();}
function setExposure(f,h){if(typeof f!=='number'||!Number.isFinite(f)||f<.1||f>1||Math.abs(f*20-Math.round(f*20))>1e-8)throw new Error('bioavailability must be 0.10–1.00 in 0.05 increments');if(!Number.isInteger(h)||h<1||h>12)throw new Error('halfLife must be an integer from 1 to 12');state.bioavailability=f;state.halfLife=h;if(state.lesson==='exposure'){ $('#bioavailability').value=f*100;$('#half-life').value=h;updateExposure();}return readState();}
function readState(){return {lesson:state.lesson,workstream:state.stream,modelEngaged:state.modelEngaged,exposure:{bioavailability:state.bioavailability,halfLife:state.halfLife,...exposureMetrics()},scope:'Educational US IND prototype. Simulated values are not clinical predictions.'};}
document.addEventListener('click',e=>{
 const l=e.target.closest('[data-lesson]');if(l){navigate(l.dataset.lesson);return;}
 const s=e.target.closest('[data-stream]');if(s){state.stream=s.dataset.stream;updateStream();return;}
 const a=e.target.closest('[data-answer]');if(a){answer(Number(a.dataset.answer));return;}
 const scene=e.target.closest('[data-scene]');if(scene){stopClip();state.clipStep=Number(scene.dataset.scene);drawClip();return;}
 const button=e.target.closest('[data-action]');if(!button)return;
 const actions={sources,about,course,challenge,experiment,worked,ai,clip,'copy-prompt':copyPrompt,'reset-exposure':()=>setExposure(.5,4),hint:()=>{$('#feedback').innerHTML='<div class="feedback"><p>Separate the measured observation from the human or safety conclusion. What additional assumption would that conclusion need?</p></div>';},'clip-play':playClip,'clip-prev':()=>{stopClip();state.clipStep=Math.max(0,state.clipStep-1);drawClip();},'clip-next':()=>{stopClip();state.clipStep=Math.min(5,state.clipStep+1);drawClip();}};
 actions[button.dataset.action]?.();
});
document.addEventListener('change',e=>{if(e.target.id==='model-engaged'){const checked=e.target.checked;setModel(checked);$('#model-engaged').focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.id==='bioavailability')setExposure(Number(e.target.value)/100,state.halfLife);if(e.target.id==='half-life')setExposure(state.bioavailability,Number(e.target.value));if(e.target.id==='experiment-note')state.experimentNote=e.target.value;});
$('#close-modal').addEventListener('click',()=>$('#modal').close());
$('#modal').addEventListener('close',stopClip);
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if([...LABS,...BRIEFS].some(l=>l.id===id))navigate(id);});
async function registerAgentTools(){
 const context=document.modelContext;if(!context?.registerTool)return;
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const objectSchema=properties=>({type:'object',properties,additionalProperties:false});
 const validate=(input,keys)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!keys.includes(k)))throw new Error('Invalid tool input');};
 const definitions=[
 {name:'read_learning_state',description:'Read the current IND lesson and illustrative model settings.',inputSchema:objectSchema({}),annotations:{readOnlyHint:true},execute(input){validate(input,[]);return readState();}},
 {name:'navigate_learning_lesson',description:'Open one of the available lessons or briefing cards.',inputSchema:{...objectSchema({lesson:{type:'string',enum:[...LABS,...BRIEFS].map(l=>l.id)}}),required:['lesson']},execute(input){validate(input,['lesson']);return navigate(input.lesson);}},
 {name:'configure_model_condition',description:'Set the hypothetical mouse intestinal target suppression and open the model lab. No clinical prediction.',inputSchema:{...objectSchema({engaged:{type:'boolean'}}),required:['engaged']},execute(input){validate(input,['engaged']);setModel(input.engaged);return navigate('model');}},
 {name:'configure_exposure_model',description:'Set bioavailability and half-life in the illustrative exposure model, then open the exposure lab. Does not select clinical doses.',inputSchema:{...objectSchema({bioavailability:{type:'number',minimum:.1,maximum:1,multipleOf:.05},halfLife:{type:'integer',minimum:1,maximum:12}}),required:['bioavailability','halfLife']},execute(input){validate(input,['bioavailability','halfLife']);setExposure(input.bioavailability,input.halfLife);return navigate('exposure');}}
 ];
 for(const tool of definitions){try{await context.registerTool({...tool,annotations:{readOnlyHint:false,untrustedContentHint:false,...tool.annotations}},{signal:lifecycle.signal});}catch{console.warn('An optional learning tool could not be registered.');}}
}
const initialLesson=location.hash.slice(1);if([...LABS,...BRIEFS].some(l=>l.id===initialLesson))state.lesson=initialLesson;
render();registerAgentTools();
window.matchMedia('(max-width:700px)').addEventListener('change',()=>{if(state.lesson==='exposure')updateExposure();});
